export const QuizRoomStatusKeyToLabel = {
  'StatusKey0': 'active',
  'StatusKey1': 'finished'
} as const;
export type QuizRoomStatusKey = keyof typeof QuizRoomStatusKeyToLabel;

export interface QuizRoom {
  /**
   * @displayName Quiz Room ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Room ID
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  roomID: string;
  /**
   * @displayName Created At
   * @validationRule Required for create/update operations
   */
  createdAt: string;
  /**
   * @displayName Current Question Index
   * @validationRule Required for create/update operations
   */
  currentQuestionIndex: number;
  /**
   * @displayName Host User ID
   * @validationRule Required for create/update operations
   */
  hostUserID: string;
  /**
   * @displayName Question Set ID
   * @validationRule Required for create/update operations
   */
  questionSetID: string;
  /**
   * @displayName Question Started At
   * @validationRule Required for create/update operations
   */
  questionStartedAt: string;
  /**
   * @displayName Round Number
   * @validationRule Required for create/update operations
   */
  roundNumber: number;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: QuizRoomStatusKey;
  /**
   * @displayName Subject
   * @validationRule Required for create/update operations
   */
  subject: string;
  /**
   * @displayName Topic
   * @validationRule Required for create/update operations
   */
  topic: string;
  /**
   * @displayName Total Rounds
   * @validationRule Required for create/update operations
   */
  totalRounds: number;
}

export const _QuizRoom = 'QuizRoom' as const;